WITH cleaned AS (SELECT *, TO_DATE(event_time) event_time_date, CONCAT(page, ' - ', event_type) page_event_type, COALESCE(page, 'DIRECT') page_clean FROM web_events WHERE page IS NOT NULL), gaps AS (SELECT *, CASE WHEN event_time - LAG(event_time) OVER (PARTITION BY session_id ORDER BY event_time, id) > INTERVAL 60 DAYS THEN 1 ELSE 0 END AS session_start_flag FROM cleaned), sessions_web_events AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY session_id ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM gaps) SELECT DATE_TRUNC('YEAR', event_time) AS year_start, DATE_TRUNC('MONTH', event_time) AS activity_month, SUM(duration_sec) AS total_duration_sec, COUNT(DISTINCT page) AS distinct_pages, ROUND(AVG(island_id), 2) AS avg_island_id, GROUPING(DATE_TRUNC('YEAR', event_time)) AS grouping_level FROM sessions_web_events GROUP BY GROUPING SETS ((DATE_TRUNC('YEAR', event_time), DATE_TRUNC('MONTH', event_time)), (DATE_TRUNC('YEAR', event_time)), ()) ORDER BY avg_island_id DESC;
